local HttpService = game:GetService("HttpService")

-- Detect the HTTP request function provided by your executor
local httpRequest = request or http_request or (syn and syn.request) or httprequest

if not httpRequest then
    warn("Your environment does not support custom HTTP requests.")
    return
end

local function joinDiscordServer(inviteCode)
    -- Discord RPC uses ports 6463 through 6472
    for port = 6463, 6472 do
        local success, result = pcall(function()
            return httpRequest({
                Url = "http://127.0.0.1:" .. tostring(port) .. "/rpc?v=1",
                Method = "POST",
                Headers = {
                    ["Content-Type"] = "application/json",
                    ["Origin"] = "https://discord.com"
                },
                Body = HttpService:JSONEncode({
                    cmd = "INVITE_BROWSER",
                    args = {
                        code = inviteCode
                    },
                    nonce = HttpService:GenerateGUID(false)
                })
            })
        end)

        -- If the request succeeded on this port, exit the loop
        if success and result and result.StatusCode == 200 then
            print("Successfully sent invite prompt to Discord on port " .. tostring(port))
            return true
        end
    end

    warn("Failed to connect to Discord desktop client. Ensure Discord is running.")
    return false
end

-- Execute the prompt with the new invite code
joinDiscordServer("zvUqqVnyn")
